#include <bits/stdc++.h>
using namespace std;

static int aCount, bCount, totalN, maxK;
static const long long MOD = 1000000007;
static long long comb[100][100];
static unordered_map<int, pair<int, long long>> stateMap;
static queue<int> stateQueue;

struct Pair {
    int depth;
    long long ways;
    Pair(int d, long long w) : depth(d), ways(w) {}
};

void processState(int state);
void updateState(int i, int j, int side, int prevState, long long edgeWays);
void computeChoose();

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> totalN >> maxK;
    aCount = 0;
    bCount = 0;
    for (int i = 0; i < totalN; i++) {
        int val;
        cin >> val;
        if (val == 50) aCount++;
        else bCount++;
    }
    computeChoose();
    int startState = 1000000 + 100 * aCount + bCount;
    stateQueue.push(startState);
    stateMap[startState] = {0, 1};
    while (!stateQueue.empty()) {
        processState(stateQueue.front());
        stateQueue.pop();
    }
    if (stateMap.count(0))
        cout << stateMap[0].first << "\n" << stateMap[0].second << "\n";
    else
        cout << -1 << "\n" << 0 << "\n";
    return 0;
}

void processState(int state) {
    int side = state / 1000000;
    int nA = (state % 1000000) / 100;
    int nB = state % 100;
    if (side > 0) {
        for (int i = nA; i >= 0 && 50 * (nA - i) <= maxK; i--) {
            for (int j = nB; j >= 0 && 50 * (nA - i) + 100 * (nB - j) <= maxK; j--) {
                if (i != nA || j != nB)
                    updateState(i, j, side, state, comb[nA][i] * comb[nB][j] % MOD);
            }
        }
    } else {
        for (int i = nA; i <= aCount && 50 * (i - nA) <= maxK; i++) {
            for (int j = nB; j <= bCount && 50 * (i - nA) + 100 * (j - nB) <= maxK; j++) {
                if (i != nA || j != nB)
                    updateState(i, j, side, state, comb[aCount - nA][i - nA] * comb[bCount - nB][j - nB] % MOD);
            }
        }
    }
}

void updateState(int i, int j, int side, int prevState, long long edgeWays) {
    int newState = 1000000 * (1 - side) + i * 100 + j;
    int newDepth = stateMap[prevState].first + 1;
    if (!stateMap.count(newState)) {
        stateMap[newState] = {newDepth, 0};
        stateQueue.push(newState);
    }
    if (stateMap[newState].first == newDepth)
        stateMap[newState].second = (stateMap[newState].second + stateMap[prevState].second * edgeWays % MOD) % MOD;
}

void computeChoose() {
    for (int i = 0; i < 100; i++) comb[i][0] = 1;
    for (int i = 1; i < 100; i++) {
        for (int j = 1; j <= i; j++) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
        }
    }
}

